import fs from 'node:fs';
import path from 'node:path';

const ROOT=process.cwd();
const ROLE='subkultur_produksjon_og_prosjekt';
const KEY=`subkultur/${ROLE}`;
const WORLD=`data/Civication/roleWorlds/subkultur/${ROLE}.json`;
const MODEL=`data/Civication/roleModels/subkultur/${ROLE}.json`;
const GRAMMAR=`data/Civication/workGrammars/subkultur/${ROLE}.json`;
const PLAN=`data/Civication/mailPlans/subkultur/${ROLE}_plan.json`;
const INDEX='data/Civication/roleWorlds/index.json';
const CHECKLIST='data/Civication/roleWorldAuthoringChecklist.json';
const THEMES='data/Civication/roleWorldThemeBank.json';
const REPORT='reports/CIVICATION_SUBKULTUR_PRODUKSJON_OG_PROSJEKT_ROLE_WORLD_ROLLOUT_SOURCE_FIRST.md';
const TEST='tests/civication-subkultur-produksjon-og-prosjekt-role-world-rollout.test.js';
const read=p=>JSON.parse(fs.readFileSync(path.join(ROOT,p),'utf8'));
const write=(p,v)=>{const full=path.join(ROOT,p);fs.mkdirSync(path.dirname(full),{recursive:true});fs.writeFileSync(full,JSON.stringify(v,null,2)+'\n','utf8')};

const grammar=read(GRAMMAR), model=read(MODEL), plan=read(PLAN);
if(plan.sequence.length!==16) throw new Error('Expected 16-step prerequisite plan');
if(grammar.persistent_work_object_contract?.id!=='prosjektplan_budsjett_kontrakt_og_avvikslogg') throw new Error('Persistent project log contract drifted');
if((model.related_people||[]).length<4) throw new Error('Expected four prerequisite work actors');

const mailRoot=path.join(ROOT,'data/Civication/mailFamilies/subkultur');
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)]);
const mailFiles=walk(mailRoot).filter(f=>f.endsWith('.json')&&path.basename(f).startsWith(ROLE+'_')).sort();
const sourceRefs=[];
for(const abs of mailFiles){
  const rel=path.relative(ROOT,abs).replaceAll('\\','/');
  const j=JSON.parse(fs.readFileSync(abs,'utf8'));
  for(const fam of j.families||[]) for(const m of fam.mails||[]) sourceRefs.push(`${rel}#${m.id}`);
}
const refs=[...new Set(sourceRefs)];
if(refs.length!==15) throw new Error(`Expected 15 authored mails, got ${refs.length}`);
const knowledgeRef=refs.find(r=>r.includes('/knowledge/'))||refs[0];

const theme_ids=['professional_culture','status_anxiety','shame_reputation','loyalty_up_down','social_mask','bureaucratic_power','precarity','public_private_leakage','care_vs_efficiency','invisible_work'];
const audienceIds=['commissioner_and_program','crew_and_technical_functions','finance_procurement_and_funders','suppliers_artists_and_rightsholders','venue_safety_and_audience','partners_and_host_institutions','private_relations'];
