const phaseActions={
  morning:'Morgenen brukes til å etablere sann status før nye løfter gis: spilleren leser siste prosjektversjon, skiller bekreftet fra betinget og navngir eier, fullmakt, avhengighet og neste kontroll. Dette er en arbeidsoperasjon, ikke en moralsk vurdering av kolleger.',
  lunch:'Ved lunsj møtes ulike interesser i samme sak. Spilleren må oversette mellom program, crew, økonomi, leverandør eller partner uten å glatte over uenighet; hvem som har sosial tyngde og hvem som faktisk kan beslutte skal forbli to forskjellige ting.',
  afternoon:'Ettermiddagen tvinger frem et konkret valg eller en handoff. Bare berørte prosjektledd gjenåpnes, tidligere versjon bevares, konsekvens for tid, kost, kvalitet, arbeidsmiljø, rettighet og sikkerhet dokumenteres, og ny status får ikke bli grønn før kontrollen finnes.',
  evening:'Kvelden viser den sosiale og private ettervirkningen av dagens prosjektarbeid. Spilleren ser hva som ble usynliggjort, hvem som bar ekstra belastning, hva som fortsatt venter, og hvordan prosjektstatus kan lekke inn i identitet og nære relasjoner dersom grensene ikke holdes.'
};
const phaseType={morning:'task',lunch:'conversation',afternoon:'decision',evening:'private_consequence'};
const coverage=[];
const phases=['morning','lunch','afternoon','evening'];
for(let d=1;d<=14;d++) for(let p=0;p<4;p++){
  const phase=phases[p], arc=dayArcs[d-1], ref=refs[coverage.length%refs.length];
  const summary=`Dag ${d}, ${phase}: ${arc[0]} ${phaseActions[phase]} Prosjektloggen «prosjektplan_budsjett_kontrakt_og_avvikslogg» er felles sannhetskilde for mandat, scope, baseline, budsjett, bestilling, kontrakt, crew, leverandør, rettighet, sikkerhet, avvik, handoff, aksept og sluttoppgjør. Spilleren må bruke presise statusord—forespurt, godkjent, bestilt, signert, levert, testet, akseptert og lukket—slik at deadline, vennskap, subkulturell kapital eller godt omdømme aldri kan late som formell fullmakt. Når premisset endres, skal bare berørte ledd åpnes på nytt, men gamle versjoner og begrunnelser bevares slik at senere konsekvenser kan spores. Dagens beat er skrevet som dramaturgisk produksjonsarbeid, ikke som ny runtime-mekanikk, og materialiseres fra den eksisterende mailen ${ref.split('#')[1]}.`;
  const audience=audienceIds[(d+p-1)%audienceIds.length];
  const standing=`Standing hos ${audience} endres langsomt ut fra det som faktisk kan observeres i denne konkrete relasjonen: om status var sann, om belastning og risiko ble synlig, om spilleren skilte koordinering fra myndighet, og om handoffen gjorde neste kontroll mulig. Et godt resultat kan derfor øke tillit hos én gruppe samtidig som en annen fortsatt er skeptisk til kostnad, programvalg eller tempo. Ingen slik standing kan gi signaturrett, budsjettmyndighet, arbeidsgiverfullmakt, rettighetsklarering, juridisk fasit eller HMS-/sikkerhetsfrigivelse. Hvis spilleren skjuler et avvik for å beskytte fremdrift eller omdømme, lagres konsekvensen redaksjonelt som et senere sosialt og profesjonelt presspunkt; hvis spilleren varsler tidlig og avgrenser rework, blir prosjektet mer reparerbart uten at konflikten forsvinner magisk.`;
  coverage.push({day:d,phase,beat_type:phaseType[phase],summary,thread_ids:[arc[1]],materialization_refs:[ref],standing_audience:audience,standing_consequence:standing});
}

