const world={
  schema:'civication_role_world_v1',version:1,category:'subkultur',role_scope:ROLE,title:'Produksjon og prosjekt — scope, leveranse, avvik og situert tillit',status:'role_world_complete',
  sociological_core:['Kulturproduksjon skjer i et felt der kreativ ambisjon, knapp tid, penger, relasjoner og offentlig forventning møtes. Produsenten får reell koordineringsmakt, men må kontinuerlig skille den fra signaturrett, arbeidsgiveransvar, rettighetsklarering og sikkerhetsmyndighet.','Prosjektets viktigste sosiale infrastruktur er sann status: hvem som tror noe er lovet, hvem som faktisk har godkjent det, hvem som bærer ekstraarbeidet, og hvilke avhengigheter som fortsatt venter. Den samme prosjektloggen gjør skjult arbeid og skjult gjeld synlig før det blir konflikt.','Langsiktig tillit oppstår ikke av et globalt omdømmetall, men situert hos oppdragsgiver, crew, økonomi, leverandører, rettighetshavere, hus, partnere og private relasjoner. De kan vurdere samme valg forskjellig uten at noen av dem kan låne spilleren formell myndighet.'],
  theme_ids,
  social_environments:['prosjektrom og milepælsmøter der bestilling, scope, baseline, endring og beslutningseier må holdes fra hverandre','budsjett-, innkjøps- og finansieringsflater der estimat, tilbud, binding, fullmakt, bestilling og prognose møter kreativ prioritering','produksjonsgulv og crewflater der kjøreplan, kompetanse, pauser, sikkerhet, rigg og faktisk fremdrift blir synlig','leverandør-, kontrakts- og rettighetsflater der versjon, kreditering, levering, aksept og betaling skaper eller bryter tillit','arena, husdrift og publikumsflate der teknisk frigivelse, tilgjengelighet og sann offentlig informasjon møter programforventning','partner- og vertsinstitusjonsrom der felles prosjekt ikke betyr felles fullmakt og handoff må tåle flere organisasjoner','privatliv og nære relasjoner der deadline, sosial status og selvkritikk kan lekke ut av prosjektet uten at fortrolige forhold skal følge med'],
  recurring_people_archetypes,slow_axes,
  situated_reputation_model:{global_score_allowed:false,audiences,authority_separation:'Situert standing må aldri blandes med program- eller kunstnerisk mandat, budsjett- og innkjøpsfullmakt, kontrakt eller signatur, arbeidsgiver- og personalansvar, rettighetsklarering, juridisk vurdering, HMS eller teknisk sikkerhetsfrigivelse. Hver beslutning må følge faktisk delegasjon og riktig faglig eier selv når sosial tillit peker i en annen retning.'},
  history_go_affordance:{source_ref:knowledgeRef,place_id:'club_7_vika',better_question:'Club 7 kan brukes som historisk produksjonslinse for å spørre hvordan et subkulturelt sted kunne holde sammen program, miljø, praktisk organisering, knappe ressurser og identitet over tid. Det bedre spørsmålet er ikke «hvordan gjorde de det, så vi kan kopiere metoden?», men hvilke avhengigheter, arbeidsformer, uformelle maktforhold og ressursvalg historien gjør synlige, og hvilke av disse som i dag må møtes med eksplisitt budsjett, kontrakt, arbeidsmiljø, rettigheter, tilgjengelighet og sikkerhetsansvar.',authority_boundary:'Historisk Club 7-kontekst kan ikke brukes som operativ fasit, juridisk kilde, HMS-standard, kontraktsfullmakt, arbeidsgiverinstruks eller rettighetsklarering i dagens prosjekt.'},
  cross_role_proof:{status:'not_materialized_no_shared_work_object',shared_work_object_found:false,new_runtime:false,candidate_when_shared_work_is_real:true,rule:'Produksjon/prosjekt kan senere kobles til en annen Role World bare når repoet beviser et reelt delt arbeidsobjekt med eksplisitt eier og handoff. Lik tematikk, samme arena eller sosial nærhet er ikke nok til å materialisere shared work object.'},
  existing_work_continuity:{work_loops:grammar.work_loops,persistent_work_object:'prosjektplan_budsjett_kontrakt_og_avvikslogg',new_runtime_state:false},
  season:{days:14,day_phases:phases,coverage},primary_threads,private_aftermath,delayed_consequences,
  materialization:{authored_dimensions:['situated_reputation'],no_new_runtime:true,existing_plan_preserved:true,existing_role_model_preserved:true,existing_people_foundation_preserved:true,existing_work_grammar_preserved:true,existing_persistent_work_preserved:true,existing_rhythm_preserved:true,cross_role_link_materialized:false,source_refs:refs}
};
write(WORLD,world);

const index=read(INDEX); index.roles=(index.roles||[]).filter(e=>!(e.category==='subkultur'&&e.role_scope===ROLE)); index.roles.push({category:'subkultur',role_scope:ROLE,status:'role_world_complete',path:WORLD}); write(INDEX,index);
const checklist=read(CHECKLIST); checklist.reference_worlds=[...new Set([...(checklist.reference_worlds||[]),WORLD])]; write(CHECKLIST,checklist);
const bank=read(THEMES); bank.reference_profiles=bank.reference_profiles||{}; bank.reference_profiles[KEY]=theme_ids; write(THEMES,bank);

const report=`# Subkultur / Produksjon og prosjekt — Role World source-first\n\n## Scope\nMaterialize one editorial \`civication_role_world_v1\` for \`${KEY}\` by reusing the already merged role model, work grammar, four fictional work actors, four work surfaces, 16-step plan, 15 authored mails and persistent \`prosjektplan_budsjett_kontrakt_og_avvikslogg\`. No new runtime is introduced.\n\n## Editorial uniqueness\nThis world is authored around cultural production and project delivery: commissioning, scope/baseline, budget and procurement, crew capacity, supplier chain, rights/credit, technical release, deviations, handoff, acceptance, settlement and closure. It is not a renamed copy of Kulturarena-ledelse.\n\n## Situated standing\nThere is no global reputation score. Seven audiences can read the same decision differently, while standing never grants signature, budget, employer, rights, legal or safety authority.\n\n## History Go\nClub 7 / \`club_7_vika\` is used only as a bounded historical production lens. It cannot answer current contract, labour, HMS, budget or rights questions.\n\n## Cross-role boundary\nStatus remains \`candidate_when_shared_work_is_real\`; no cross-role link is materialized because no governed shared work object is proven.\n\n## Season proof\n14 days × 4 phases = 56 unique beats; 7 primary threads; 8 delayed consequences; 5 private aftermath beats; all 15 authored mails are used repeatedly as provenance.\n\n## Quality gate\nInternal editorial target: 29/30. The package favors exact status language, distributed authority, bounded rework, delayed consequences, work/private leakage and professional culture without inventing new gameplay state.\n`;
fs.mkdirSync(path.dirname(path.join(ROOT,REPORT)),{recursive:true});fs.writeFileSync(path.join(ROOT,REPORT),report,'utf8');

const test=`const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');\nconst R=path.resolve(__dirname,'..'),read=p=>JSON.parse(fs.readFileSync(path.join(R,p),'utf8')),KEY='${KEY}',ROLE='${ROLE}',WORLD='${WORLD}',PLAN='${PLAN}',MODEL='${MODEL}',GRAMMAR='${GRAMMAR}';\nconst world=read(WORLD);assert.equal(world.schema,'civication_role_world_v1');assert.equal(world.status,'role_world_complete');assert.deepEqual(world.materialization.authored_dimensions,['situated_reputation']);\nfor(const k of ['no_new_runtime','existing_plan_preserved','existing_role_model_preserved','existing_people_foundation_preserved','existing_work_grammar_preserved','existing_persistent_work_preserved','existing_rhythm_preserved']) assert.equal(world.materialization[k],true,k);\nassert.equal(world.materialization.cross_role_link_materialized,false);assert.deepEqual(world.existing_work_continuity.work_loops,read(GRAMMAR).work_loops);assert.equal(world.existing_work_continuity.persistent_work_object,'prosjektplan_budsjett_kontrakt_og_avvikslogg');assert.equal(world.existing_work_continuity.new_runtime_state,false);assert.equal(read(PLAN).sequence.length,16);\nfor(const p of read(MODEL).related_people){assert.equal(p.fictional,true);assert.equal(p.fictional_scenario_actor,true);assert.equal(p.canonical_person_ref,null)}\nconst refs=world.materialization.source_refs;assert.equal(refs.length,15);assert.equal(new Set(refs).size,15);for(const ref of refs){const[f,id]=ref.split('#');assert.ok(read(f).families.flatMap(x=>x.mails||[]).some(m=>m.id===id),ref)}\nconst audienceIds=${JSON.stringify(audienceIds)};assert.equal(world.situated_reputation_model.global_score_allowed,false);assert.deepEqual(world.situated_reputation_model.audiences.map(a=>a.id),audienceIds);assert.equal(new Set(world.situated_reputation_model.audiences.map(a=>a.standing_axis)).size,audienceIds.length);for(const a of world.situated_reputation_model.audiences){assert.ok(a.cares_about.length>=2);assert.match(a.cannot_grant,/ikke|kan ikke/i)}\nfor(const term of [/program|kunstnerisk/i,/budsjett|innkjøp/i,/kontrakt|signatur/i,/arbeidsgiver|personal/i,/rettighet/i,/HMS|sikkerhet/i,/juridisk/i]) assert.match(world.situated_reputation_model.authority_separation,term);for(const axis of world.slow_axes) assert.equal(axis.runtime_binding,'editorial_only_until_governed');assert.ok(world.slow_axes.length>=8);\nassert.ok(refs.includes(world.history_go_affordance.source_ref));assert.equal(world.history_go_affordance.place_id,'club_7_vika');assert.ok(world.history_go_affordance.better_question.length>=300);assert.match(world.history_go_affordance.better_question,/Club 7/);assert.match(world.history_go_affordance.authority_boundary,/ikke|kan ikke/i);\nassert.equal(world.cross_role_proof.status,'not_materialized_no_shared_work_object');assert.equal(world.cross_role_proof.shared_work_object_found,false);assert.equal(world.cross_role_proof.new_runtime,false);assert.equal(world.cross_role_proof.candidate_when_shared_work_is_real,true);assert.match(world.cross_role_proof.rule,/shared work object|delt arbeidsobjekt/i);\nassert.equal(world.season.days,14);assert.deepEqual(world.season.day_phases,['morning','lunch','afternoon','evening']);assert.equal(world.season.coverage.length,56);const beatKeys=new Set(world.season.coverage.map(b=>b.day+'/'+b.phase));assert.equal(beatKeys.size,56);assert.equal(new Set(world.season.coverage.map(b=>b.summary)).size,56);assert.equal(new Set(world.season.coverage.map(b=>b.standing_consequence)).size,56);const uses=new Map(refs.map(r=>[r,0]));for(const b of world.season.coverage){assert.ok(b.summary.length>=620,b.day+'/'+b.phase+' summary '+b.summary.length);assert.ok(b.standing_consequence.length>=500,b.day+'/'+b.phase+' standing '+b.standing_consequence.length);assert.ok(audienceIds.includes(b.standing_audience));assert.equal(b.materialization_refs.length,1);assert.ok(refs.includes(b.materialization_refs[0]));uses.set(b.materialization_refs[0],uses.get(b.materialization_refs[0])+1)}for(const[r,n] of uses) assert.ok(n>=3,r+' underused '+n);\nassert.equal(world.primary_threads.length,7);for(const t of world.primary_threads){assert.ok(t.relationship.length>=160);assert.ok(t.beat_refs.length>=5&&t.beat_refs.length<=10);assert.ok(new Set(t.beat_refs.map(r=>r.split('/')[0])).size>=3);for(const r of t.beat_refs) assert.ok(beatKeys.has(r),r)}assert.equal(world.private_aftermath.length,5);for(const x of world.private_aftermath){assert.ok(x.meaning.length>=140);for(const r of x.beat_refs) assert.ok(beatKeys.has(r),r)}assert.equal(world.delayed_consequences.length,8);const order=r=>{const[d,p]=r.split('/');return Number(d)*10+({morning:1,lunch:2,afternoon:3,evening:4}[p]||0)};for(const x of world.delayed_consequences){assert.ok(beatKeys.has(x.setup_ref));assert.ok(beatKeys.has(x.return_ref));assert.ok(order(x.return_ref)>order(x.setup_ref))}\nconst index=read('data/Civication/roleWorlds/index.json');assert.deepEqual(index.roles.find(e=>e.category==='subkultur'&&e.role_scope===ROLE),{category:'subkultur',role_scope:ROLE,status:'role_world_complete',path:WORLD});assert.ok(read('data/Civication/roleWorldAuthoringChecklist.json').reference_worlds.includes(WORLD));assert.deepEqual(read('data/Civication/roleWorldThemeBank.json').reference_profiles[KEY],world.theme_ids);const readiness=read('data/Civication/roleWorldRolloutReadiness.json');assert.ok(!(readiness.rollout_queue||[]).some(e=>e.key===KEY));assert.equal(readiness.roles.find(e=>e.key===KEY).role_world_status,'role_world_complete');assert.ok(readiness.summary.role_world_complete_or_pilot>=53);assert.equal(readiness.gate.gate_pass,true);const career=read('data/Civication/careerGameplayMatrix.json').worlds.find(e=>e.key===KEY);assert.equal(career.status,'playable');assert.equal(career.audit.runtime_gate,true);assert.deepEqual(career.audit.missing_components,[]);assert.equal(read(GRAMMAR).persistent_work_object_contract.id,'prosjektplan_budsjett_kontrakt_og_avvikslogg');const source=fs.readFileSync(path.join(R,'${REPORT}'),'utf8');assert.match(source,/Editorial uniqueness/i);assert.match(source,/global reputation score/i);assert.match(source,/candidate_when_shared_work_is_real/);assert.match(source,/29\\/30/);console.log('Civication Subkultur Produksjon og prosjekt Role World rollout: OK');\n`;
fs.writeFileSync(path.join(ROOT,TEST),test,'utf8');
